contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 _x, bytes32 _y) public {
        bool beforeStatus = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        bool returned;
        bool reverted;
        bool r = c.logRegisteredPubkey(_x, _y); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            returned = r;
            reverted = false;
        }

        bool afterStatus = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted && returned == beforeStatus && afterStatus == beforeStatus);
    }

    receive() external payable {}
}

