pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(bytes32 _x, bytes32 _y) internal {
        bool beforeStatus;
        try c.approvedToLog(address(this)) returns (bool __r) { beforeStatus = __r; } catch { return; }
        bool returned;
        bool reverted;
        try c.logRegisteredPubkey(_x, _y) returns (bool r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterStatus;
        try c.approvedToLog(address(this)) returns (bool __r) { afterStatus = __r; } catch { return; }
        assertTrue(!reverted && returned == beforeStatus && afterStatus == beforeStatus);
    }

    function testFuzz_run(bytes32 _x, bytes32 _y) public {
        _run(_x, _y);
    }

    receive() external payable {}
}
